import React, { useEffect, useState } from "react";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";
import ProfileHeader from "../../components/common/ProfileHeader";
import LoyaltyTile from "../../components/common/LoyaltyTile";
import TextBox from "../../components/common/TextBox";
import Button from "../../components/common/Button";

/* ---- Styled Wrappers ---- */
const PageWrapper = styled.div`
  background-color: ${({ theme }) => theme.colors.background};
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 90%;
  max-width: 1200px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 60px 0;
`;

const Card = styled.div`
  background: #fff;
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
`;

const SectionTitle = styled.h2`
  font-size: 20px;
  font-weight: 700;
  color: #2d2d2d;
  margin-bottom: 20px;
`;

const HeaderRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
`;

const LoyaltyList = styled.div`
  display: flex;
  flex-direction: column;
  gap: 16px;
`;

const ProfilePage: React.FC = () => {
  const [isEditing, setIsEditing] = useState(false);
  const [customer, setCustomer] = useState<any>(null);

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");

  // Load user
  useEffect(() => {
    const stored = localStorage.getItem("customer");
    if (stored) {
      const data = JSON.parse(stored);
      const fullName = `${data.firstName} ${data.lastName}`;
      setCustomer(data);
      setName(fullName);
      setEmail(data.email);
    }

    const token = localStorage.getItem("customerToken");
    if (token) {
      fetch("http://localhost:5000/api/customers/me", {
        headers: { Authorization: `Bearer ${token}` },
      })
        .then((res) => res.json())
        .then((data) => {
          const fullName = `${data.firstName} ${data.lastName}`;
          setCustomer(data);
          setName(fullName);
          setEmail(data.email);
          localStorage.setItem("customer", JSON.stringify(data));
        })
        .catch(() => {});
    }
  }, []);

  if (!customer) return <div style={{ padding: 40 }}>Loading...</div>;

  const handleSave = async () => {
    const token = localStorage.getItem("customerToken");
    if (!token) return;

    // Split name into first + last
    const parts = name.trim().split(" ");
    const firstName = parts[0];
    const lastName = parts.slice(1).join(" ") || "";

    const res = await fetch("http://localhost:5000/api/customers/me", {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        firstName,
        lastName,
        email,
      }),
    });

    const data = await res.json();

    if (res.ok) {
      setCustomer(data.customer);
      localStorage.setItem("customer", JSON.stringify(data.customer));
      setIsEditing(false);
    } else {
      alert(data.message || "Failed to update profile");
    }
  };

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        {/* Header */}
        <ProfileHeader
          type="customer"
          name={name}
          stat1={0}
          stat2={0}
          stat3={0}
        />

        {/* Personal Info */}
        <Card>
          <HeaderRow>
            <SectionTitle>Personal Information</SectionTitle>
            <Button
              onClick={() => (isEditing ? handleSave() : setIsEditing(true))}
              style={{
                padding: "8px 16px",
                fontSize: "14px",
                borderRadius: "8px",
                width: "auto",
              }}
            >
              {isEditing ? "Save" : "Edit"}
            </Button>
          </HeaderRow>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "16px",
            }}
          >
            <TextBox
              label="Name"
              value={name}
              readOnly={!isEditing}
              onChange={(e: any) => setName(e.target.value)}
            />

            {/* Phone Removed */}

            <div style={{ gridColumn: "1 / span 2" }}>
              <TextBox
                label="Email"
                value={email}
                readOnly={!isEditing}
                onChange={(e: any) => setEmail(e.target.value)}
                style={{ width: "100%" }}
              />
            </div>
          </div>
        </Card>

        {/* Loyalty Card UI stays the same */}
        <Card>
          <SectionTitle>My Loyalty Programs</SectionTitle>
          <LoyaltyList>
            <div style={{ color: "#999" }}>No loyalty programs yet</div>
          </LoyaltyList>
        </Card>
      </ContentWrapper>
    </PageWrapper>
  );
};

export default ProfilePage;
